from itertools import product
from typing import Dict, List, Tuple

Lattice = Tuple[int, ...]

def lattice_points(n: int, m: int) -> List[Lattice]:
    return [c for c in product(range(m + 1), repeat=n + 1) if sum(c) == m]

def upward_cells_2d(m: int) -> List[Tuple[Lattice, Lattice, Lattice]]:
    cells = []
    for a in range(m + 1):
        for b in range(m + 1 - a):
            c = m - a - b
            if c >= 1:
                cells.append(((a + 1, b, c - 1), (a, b + 1, c - 1), (a, b, c)))
    return cells

def count_rainbow(m: int) -> int:
    pts = lattice_points(2, m)
    coloring: Dict[Lattice, int] = {k: max(i for i in range(3) if k[i] != 0) for k in pts}
    assert all(k[c] != 0 for k, c in coloring.items()), "coloring must be proper"
    target = {0, 1, 2}
    return sum(1 for cell in upward_cells_2d(m) if {coloring[v] for v in cell} == target)

if __name__ == "__main__":
    for m in (2, 4, 6, 8, 12):
        r = count_rainbow(m)
        print(f"m={m:2d}: rainbow cells = {r}  ({'ODD' if r % 2 else 'EVEN'})")

from itertools import product
from typing import Callable, Dict, List, Tuple

Vector = Tuple[float, ...]
Lattice = Tuple[int, ...]

def lattice_points(n: int, m: int) -> List[Lattice]:
    return [c for c in product(range(m + 1), repeat=n + 1) if sum(c) == m]

def lattice_vertex(m: int, k: Lattice) -> Vector:
    return tuple(ki / m for ki in k)

def descent_coordinate(f: Callable[[Vector], Vector], v: Vector) -> int:
    fv = f(v)
    for i, vi in enumerate(v):
        if vi > 1e-15 and fv[i] <= vi + 1e-12:
            return i
    return max(range(len(v)), key=lambda i: v[i])

def upward_cells_2d(m: int):
    cells = []
    for a in range(m + 1):
        for b in range(m + 1 - a):
            c = m - a - b
            if c >= 1:
                cells.append(((a + 1, b, c - 1), (a, b + 1, c - 1), (a, b, c)))
    return cells

def approximate_fixed_point(f: Callable[[Vector], Vector], m: int) -> Tuple[Vector, float]:
    pts = lattice_points(2, m)
    coloring: Dict[Lattice, int] = {k: descent_coordinate(f, lattice_vertex(m, k)) for k in pts}
    best_pt, best_res = lattice_vertex(m, pts[0]), float("inf")
    for cell in upward_cells_2d(m):
        if {coloring[v] for v in cell} != {0, 1, 2}:
            continue
        center = tuple(sum(lattice_vertex(m, v)[i] for v in cell) / 3 for i in range(3))
        fc = f(center)
        res = max(abs(fc[i] - center[i]) for i in range(3))
        if res < best_res:
            best_res, best_pt = res, center
    return best_pt, best_res

if __name__ == "__main__":
    target = (0.5, 1/3, 1/6)
    def f(v: Vector) -> Vector:
        w = tuple(0.5 * v[i] + 0.5 * target[i] for i in range(3))
        s = sum(w)
        return tuple(wi / s for wi in w)
    for m in (8, 16, 32, 64):
        x, res = approximate_fixed_point(f, m)
        print(f"m={m:3d}: x~{tuple(round(t,4) for t in x)}  |f(x)-x|={res:.5f}")

