function ImprovementStep(payoffs u, profile sigma):
    for each player p:
        base <- expected payoff of p under sigma
        for each pure action a of p:
            gain[p,a] <- max(0, u_p(a, sigma_{-p}) - base)
        for each pure action a of p:
            sigma'[p,a] <- (sigma[p,a] + gain[p,a]) / (1 + sum_b gain[p,b])
    return sigma'

function FindNash(payoffs, grid):
    best <- +infinity
    for each profile sigma on the grid of the strategy product:
        r <- max over players p of (best deviation payoff of p - u_p(sigma))
        if r < best: best <- r; sigma* <- sigma
    return sigma*        # max regret 0 => Nash equilibrium / fixed point of g
